SELECT CAST(j.commit.collection AS VARCHAR) AS event, date_part('hour', make_timestamp(CAST(CAST(j.time_us AS BIGINT) / 1000000 AS BIGINT))) AS hour_of_day, count(*) AS count FROM bluesky WHERE CAST(j.kind AS VARCHAR) = 'commit' AND CAST(j.commit.operation AS VARCHAR) = 'create' AND CAST(j.commit.collection AS VARCHAR) IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
